import AppKit
import ApplicationServices
import CoreGraphics
import Foundation
import OperonSystemSoftware

/// Marks CGEvents generated by Computer Use so the host's physical-input monitor
/// can distinguish them from real user input.
public enum ComputerUseSyntheticInputMarker {
    public static let value: Int64 = 0x4f_50_43_55 // "OPCU"

    public static func apply(to event: CGEvent) {
        event.setIntegerValueField(.eventSourceUserData, value: value)
    }
}

enum MouseButtonKind: String {
    case left
    case right
    case middle

    var cgButton: CGMouseButton {
        switch self {
        case .left:
            return .left
        case .right:
            return .right
        case .middle:
            return .center
        }
    }

    var downEvent: CGEventType {
        switch self {
        case .left:
            return .leftMouseDown
        case .right:
            return .rightMouseDown
        case .middle:
            return .otherMouseDown
        }
    }

    var upEvent: CGEventType {
        switch self {
        case .left:
            return .leftMouseUp
        case .right:
            return .rightMouseUp
        case .middle:
            return .otherMouseUp
        }
    }
}

/// Codex `ApplicationUIElement.MouseEventTarget` — destination for a process-
/// local pointer event.
struct MouseEventTarget: Equatable, Sendable {
    let pid: pid_t
    let windowID: CGWindowID
    let windowBounds: CGRect
    /// When true, window-local Y is measured from the top edge (CG / flipped
    /// AppKit views, Electron). When false, from the bottom edge (classic
    /// non-flipped AppKit window base coordinates).
    /// Mirrors official `windowUsesFlippedCoordinates`.
    let windowUsesFlippedCoordinates: Bool
}

/// Convert a global CG (top-left origin) point into NSEvent window-local coords.
func windowLocalPoint(
    globalPoint: CGPoint,
    windowBounds: CGRect,
    windowUsesFlippedCoordinates: Bool
) -> CGPoint {
    let x = globalPoint.x - windowBounds.minX
    let yFromTop = globalPoint.y - windowBounds.minY
    if windowUsesFlippedCoordinates {
        return CGPoint(x: x, y: yFromTop)
    }
    return CGPoint(x: x, y: windowBounds.height - yFromTop)
}

/// The point `CGSEventSetWindowLocation` wants: window-local, **top-left
/// origin**, regardless of the window's AppKit coordinate flipping.
///
/// Measured, not inferred (A/B/A against the AppKit fixture, target in the
/// background the whole time — `scratchpad/probe2.swift`):
///
/// | stamped local point | background scroll | background click |
/// |---|---|---|
/// | top-left origin (`yFromTop`) | MOVED 3/3 | CLICKED 2/2 |
/// | bottom-left origin (`height - yFromTop`) | no effect | no effect |
/// | top-left origin but a different element's point | no effect | — |
///
/// The third row is the important one: the receiving process hit-tests with
/// exactly this value, so the polarity is not cosmetic. Electron/Chromium
/// windows were already stamped top-down (they are classified flipped), which
/// is why background clicks worked there and never on classic AppKit windows.
func windowServerLocalPoint(
    globalPoint: CGPoint,
    windowBounds: CGRect
) -> CGPoint {
    CGPoint(
        x: globalPoint.x - windowBounds.minX,
        y: globalPoint.y - windowBounds.minY
    )
}

enum InputSimulation {
    static let maxKeyboardUnicodeChunkLength = 64

    /// Global pointer fallback must never activate or raise the target.
    ///
    /// Codex keeps the system front process and window z-order untouched.
    /// `NSRunningApplication.activate` and `AXRaise` both produce a visible
    /// flash; background operation posts events with `postToPid` instead.
    static func prepareAppForGlobalPointerInput(_ app: RunningAppDescriptor) {
        _ = app
        // Intentionally a no-op. Callers that still hit the global HID path
        // already hold synthetic focus via SyntheticAppFocusEnforcer.
    }

    static func clickGlobally(at point: CGPoint, button: MouseButtonKind, clickCount: Int) throws {
        guard let source = CGEventSource(stateID: .hidSystemState) else {
            throw ComputerUseError.message("Failed to create HID event source.")
        }

        for _ in 0..<max(clickCount, 1) {
            try postMouseEvent(type: .mouseMoved, source: source, point: point, button: button.cgButton, clickState: clickCount)
            try postMouseEvent(type: button.downEvent, source: source, point: point, button: button.cgButton, clickState: clickCount)
            try postMouseEvent(type: button.upEvent, source: source, point: point, button: button.cgButton, clickState: clickCount)
        }
    }

    /// Codex `ApplicationUIElement.sendClick(to:at:insideWebView:...)`.
    /// Posts move + down + up to the target pid with window-tagged events.
    static func sendClick(
        to target: MouseEventTarget,
        at globalPoint: CGPoint,
        button: MouseButtonKind,
        clickCount: Int
    ) throws {
        guard let source = CGEventSource(stateID: .combinedSessionState) else {
            throw ComputerUseError.message("Failed to create targeted event source.")
        }

        for _ in 0..<max(clickCount, 1) {
            // Official `sendClick` posts down+up only; the extra move is ours.
            // Measured harmless (3/3 with and without), and it keeps Chromium's
            // hover state consistent with where we are about to click.
            try postMouseEventToPid(
                type: .mouseMoved,
                source: source,
                point: globalPoint,
                button: button.cgButton,
                clickState: clickCount,
                target: target
            )
            try postMouseEventToPid(
                type: button.downEvent,
                source: source,
                point: globalPoint,
                button: button.cgButton,
                clickState: clickCount,
                target: target
            )
            try postMouseEventToPid(
                type: button.upEvent,
                source: source,
                point: globalPoint,
                button: button.cgButton,
                clickState: clickCount,
                target: target
            )
        }
    }

    static func clickTargeted(
        at point: CGPoint,
        button: MouseButtonKind,
        clickCount: Int,
        pid: pid_t,
        windowID: CGWindowID?,
        windowBounds: CGRect?,
        windowUsesFlippedCoordinates: Bool = true
    ) throws {
        if let windowID, let windowBounds, windowID != 0, windowBounds.width > 1 {
            try sendClick(
                to: MouseEventTarget(
                    pid: pid,
                    windowID: windowID,
                    windowBounds: windowBounds,
                    windowUsesFlippedCoordinates: windowUsesFlippedCoordinates
                ),
                at: point,
                button: button,
                clickCount: clickCount
            )
            return
        }

        guard let source = CGEventSource(stateID: .combinedSessionState) else {
            throw ComputerUseError.message("Failed to create targeted event source.")
        }

        for _ in 0..<max(clickCount, 1) {
            try postMouseEventToPid(
                type: .mouseMoved,
                source: source,
                point: point,
                button: button.cgButton,
                clickState: clickCount,
                pid: pid,
                windowID: windowID,
                windowBounds: windowBounds,
                windowUsesFlippedCoordinates: windowUsesFlippedCoordinates
            )
            try postMouseEventToPid(
                type: button.downEvent,
                source: source,
                point: point,
                button: button.cgButton,
                clickState: clickCount,
                pid: pid,
                windowID: windowID,
                windowBounds: windowBounds,
                windowUsesFlippedCoordinates: windowUsesFlippedCoordinates
            )
            try postMouseEventToPid(
                type: button.upEvent,
                source: source,
                point: point,
                button: button.cgButton,
                clickState: clickCount,
                pid: pid,
                windowID: windowID,
                windowBounds: windowBounds,
                windowUsesFlippedCoordinates: windowUsesFlippedCoordinates
            )
        }
    }

    static func scrollTargeted(
        at point: CGPoint,
        direction: String,
        pages: Double,
        pid: pid_t,
        windowID: CGWindowID?,
        windowBounds: CGRect? = nil
    ) throws {
        // Sky API is direction+pages; convert to Codex deltaX/deltaY form.
        try scrollTargeted(
            at: point,
            deltaX: Int(wheel2(direction: direction, pages: pages)),
            deltaY: Int(wheel1(direction: direction, pages: pages)),
            pid: pid,
            windowID: windowID,
            windowBounds: windowBounds
        )
    }

    /// Codex `ComputerUseAppController.scroll(deltaX:deltaY:)` shape.
    ///
    /// Field packing follows official `SynthesizedEvent.scroll(at:deltaX:deltaY:
    /// inWindow:windowBounds:windowUsesFlippedCoordinates:)`:
    ///
    ///   source = sourceCreate(stateID: 1)            // kCGEventSourceStateHIDSystemState
    ///   createScrollWheelEvent(source, units, count, wheel1: deltaY, wheel2: deltaX, 0)
    ///   setLocation(event, point)
    ///   if let windowID { setIntegerValueField(51 / 91 / 92, windowID) }
    ///   if let bounds {
    ///       local = CGPointApplyAffineTransform(getLocation(event),
    ///                                           translate(-minX, -minY))
    ///       if flipped { local.y = height - local.y }
    ///       WindowServerSPI.setWindowLocation(event, local)
    ///   }
    ///
    /// The last step is the one that made background *clicks* land (§1.24); the
    /// scroll path never had it, which is why a background scroll reported
    /// success and moved nothing.
    static func scrollTargeted(
        at point: CGPoint,
        deltaX: Int,
        deltaY: Int,
        pid: pid_t,
        windowID: CGWindowID?,
        windowBounds: CGRect? = nil
    ) throws {
        guard let event = CGEvent(
            scrollWheelEvent2Source: CGEventSource(stateID: .hidSystemState),
            units: .line,
            wheelCount: 2,
            wheel1: Int32(deltaY),
            wheel2: Int32(deltaX),
            wheel3: 0
        ) else {
            throw ComputerUseError.message("Failed to create scroll event.")
        }

        event.location = point
        if let windowID {
            // Official writes 51 (undocumented, scroll-specific) plus the two
            // window-under-pointer fields; it does *not* write mouse subtype 3
            // on scroll events.
            event.setIntegerValueField(
                CGEventField(rawValue: 51)!,
                value: Int64(windowID)
            )
            event.setIntegerValueField(
                .mouseEventWindowUnderMousePointer,
                value: Int64(windowID)
            )
            event.setIntegerValueField(
                .mouseEventWindowUnderMousePointerThatCanHandleThisEvent,
                value: Int64(windowID)
            )
        }
        if let windowBounds {
            WindowServerEventSPI.setWindowLocation(
                event,
                location: windowServerLocalPoint(
                    globalPoint: point,
                    windowBounds: windowBounds
                )
            )
        }
        ComputerUseSyntheticInputMarker.apply(to: event)
        event.postToPid(pid)
        Thread.sleep(forTimeInterval: 0.1)
    }

    static func scrollGlobally(at point: CGPoint, direction: String, pages: Double) throws {
        guard let event = CGEvent(scrollWheelEvent2Source: nil, units: .line, wheelCount: 2, wheel1: wheel1(direction: direction, pages: pages), wheel2: wheel2(direction: direction, pages: pages), wheel3: 0) else {
            throw ComputerUseError.message("Failed to create scroll event.")
        }

        event.location = point
        ComputerUseSyntheticInputMarker.apply(to: event)
        event.post(tap: .cghidEventTap)
        Thread.sleep(forTimeInterval: 0.1)
    }

    static func dragTargeted(
        from start: CGPoint,
        to end: CGPoint,
        pid: pid_t,
        windowID: CGWindowID?,
        windowBounds: CGRect?
    ) throws {
        guard let source = CGEventSource(stateID: .combinedSessionState) else {
            throw ComputerUseError.message("Failed to create targeted event source.")
        }

        try postMouseEventToPid(type: .mouseMoved, source: source, point: start, button: .left, clickState: 1, pid: pid, windowID: windowID, windowBounds: windowBounds)
        try postMouseEventToPid(type: .leftMouseDown, source: source, point: start, button: .left, clickState: 1, pid: pid, windowID: windowID, windowBounds: windowBounds)

        for step in 1...10 {
            let progress = CGFloat(step) / 10
            let point = CGPoint(
                x: start.x + ((end.x - start.x) * progress),
                y: start.y + ((end.y - start.y) * progress)
            )
            try postMouseEventToPid(type: .leftMouseDragged, source: source, point: point, button: .left, clickState: 1, pid: pid, windowID: windowID, windowBounds: windowBounds)
        }

        try postMouseEventToPid(type: .leftMouseUp, source: source, point: end, button: .left, clickState: 1, pid: pid, windowID: windowID, windowBounds: windowBounds)
    }

    static func dragGlobally(from start: CGPoint, to end: CGPoint) throws {
        guard let source = CGEventSource(stateID: .hidSystemState) else {
            throw ComputerUseError.message("Failed to create HID event source.")
        }

        try postMouseEvent(type: .mouseMoved, source: source, point: start, button: .left, clickState: 1)
        try postMouseEvent(type: .leftMouseDown, source: source, point: start, button: .left, clickState: 1)

        for step in 1...10 {
            let progress = CGFloat(step) / 10
            let point = CGPoint(
                x: start.x + ((end.x - start.x) * progress),
                y: start.y + ((end.y - start.y) * progress)
            )
            try postMouseEvent(type: .leftMouseDragged, source: source, point: point, button: .left, clickState: 1)
        }

        try postMouseEvent(type: .leftMouseUp, source: source, point: end, button: .left, clickState: 1)
    }

    /// Official `SynthesizedEvent.type(string:)` builds keyboard
    /// events from `CGEventAPI.sourceCreate(stateID:)` with `w0 = 1`
    /// (`kCGEventSourceStateHIDSystemState`); both our keyboard paths passed `nil`.
    ///
    /// **A/B'd: no observable behavioural difference** — `type` lands with either,
    /// and `pressKey`'s background failure is unaffected. Kept purely as parity
    /// with the binary; do not cite it as a fix for anything.
    static func keyboardEventSource() -> CGEventSource? {
        CGEventSource(stateID: .hidSystemState)
    }

    /// Post one key press the way Codex's builder does: a real
    /// key code, the modifier flags, **and** the unicode string — on the keyUp as
    /// well as the keyDown.
    ///
    /// Setting only some of those is what broke our two old paths: an app that
    /// reads the key code (native AppKit) ignored `typeText`'s `virtualKey: 0`
    /// events, and `pressKey` sent no string at all.
    static func postKeyPress(_ press: VirtualKeyPress, pid: pid_t) throws {
        let source = keyboardEventSource()
        guard
            let down = CGEvent(keyboardEventSource: source, virtualKey: press.keyCode, keyDown: true),
            let up = CGEvent(keyboardEventSource: source, virtualKey: press.keyCode, keyDown: false)
        else {
            throw ComputerUseError.message("Failed to create keyboard event.")
        }

        for event in [down, up] {
            event.flags = press.modifiers
            if !press.string.isEmpty {
                var units = Array(press.string.utf16)
                units.withUnsafeMutableBufferPointer { buffer in
                    guard let base = buffer.baseAddress else {
                        return
                    }
                    event.keyboardSetUnicodeString(stringLength: buffer.count, unicodeString: base)
                }
            }
            ComputerUseSyntheticInputMarker.apply(to: event)
        }

        down.postToPid(pid)
        up.postToPid(pid)
    }

    static func typeText(_ text: String, pid: pid_t) throws {
        // Codex `SynthesizedEvent.type(string:)` runs the string
        // through `+[SAIVirtualKeyPress keyPressesForString:]` and then through
        // the same `pressKeys` primitive an explicit key press uses — there is no
        // separate "inject unicode" path in the official service.
        for press in VirtualKeyPress.presses(for: text) {
            try postKeyPress(press, pid: pid)
            Thread.sleep(forTimeInterval: 0.02)
        }
    }

    static func keyboardUnicodeChunks(for text: String, maxUTF16Units: Int = maxKeyboardUnicodeChunkLength) -> [[UniChar]] {
        precondition(maxUTF16Units > 0, "maxUTF16Units must be positive")

        var chunks: [[UniChar]] = []
        var current: [UniChar] = []

        for character in text {
            let units = Array(String(character).utf16)
            if !current.isEmpty, current.count + units.count > maxUTF16Units {
                chunks.append(current)
                current.removeAll(keepingCapacity: true)
            }

            current.append(contentsOf: units)
        }

        if !current.isEmpty {
            chunks.append(current)
        }

        return chunks
    }

    static func pressKey(_ specification: String, pid: pid_t) throws {
        let parsed = try KeyPressParser.parse(specification)
        var activeFlags: CGEventFlags = []

        for modifier in parsed.modifiers {
            guard let event = CGEvent(keyboardEventSource: keyboardEventSource(), virtualKey: modifier.keyCode, keyDown: true) else {
                throw ComputerUseError.message("Failed to create modifier key down event.")
            }

            activeFlags.insert(modifier.flag)
            event.flags = activeFlags
            ComputerUseSyntheticInputMarker.apply(to: event)
            event.postToPid(pid)
        }

        // Same primitive `typeText` uses, so the key event carries a unicode
        // string as well as the key code — the official builder always sets both
        //, and we used to send key presses with no string.
        try postKeyPress(
            VirtualKeyPress(
                keyCode: parsed.keyCode,
                modifiers: activeFlags,
                string: KeyPressParser.characters(for: parsed.keyCode, modifiers: activeFlags)
            ),
            pid: pid
        )

        for modifier in parsed.modifiers.reversed() {
            guard let event = CGEvent(keyboardEventSource: keyboardEventSource(), virtualKey: modifier.keyCode, keyDown: false) else {
                throw ComputerUseError.message("Failed to create modifier key up event.")
            }

            event.flags = activeFlags
            ComputerUseSyntheticInputMarker.apply(to: event)
            event.postToPid(pid)
            activeFlags.remove(modifier.flag)
        }

        Thread.sleep(forTimeInterval: 0.1)
    }

    private static func postMouseEvent(type: CGEventType, source: CGEventSource, point: CGPoint, button: CGMouseButton, clickState: Int) throws {
        guard let event = CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: button) else {
            throw ComputerUseError.message("Failed to create mouse event \(type.rawValue).")
        }

        event.setIntegerValueField(.mouseEventClickState, value: Int64(clickState))
        ComputerUseSyntheticInputMarker.apply(to: event)
        event.post(tap: .cghidEventTap)
        Thread.sleep(forTimeInterval: 0.03)
    }

    private static func postMouseEventToPid(
        type: CGEventType,
        source: CGEventSource,
        point: CGPoint,
        button: CGMouseButton,
        clickState: Int,
        target: MouseEventTarget
    ) throws {
        try postMouseEventToPid(
            type: type,
            source: source,
            point: point,
            button: button,
            clickState: clickState,
            pid: target.pid,
            windowID: target.windowID,
            windowBounds: target.windowBounds,
            windowUsesFlippedCoordinates: target.windowUsesFlippedCoordinates
        )
    }

    private static func postMouseEventToPid(
        type: CGEventType,
        source: CGEventSource,
        point: CGPoint,
        button: CGMouseButton,
        clickState: Int,
        pid: pid_t,
        windowID: CGWindowID?,
        windowBounds: CGRect?,
        windowUsesFlippedCoordinates: Bool = true
    ) throws {
        guard let event = targetedWindowMouseEvent(
            type: type,
            point: point,
            button: button,
            clickState: clickState,
            windowID: windowID,
            windowBounds: windowBounds,
            windowUsesFlippedCoordinates: windowUsesFlippedCoordinates
        ) ?? CGEvent(
            mouseEventSource: source,
            mouseType: type,
            mouseCursorPosition: point,
            mouseButton: button
        ) else {
            throw ComputerUseError.message("Failed to create mouse event \(type.rawValue).")
        }

        event.timestamp = CGEventTimestamp(
            ProcessInfo.processInfo.systemUptime * 1_000_000_000
        )
        event.flags = []
        // Two fields the official factory does not write. Measured harmless:
        // dropping both still lands 3/3 background clicks, so they stay — the
        // marker is what lets UserInterruptionMonitor tell our events from the
        // user's.
        event.setIntegerValueField(.mouseEventClickState, value: Int64(clickState))
        // targetedWindowMouseEvent already packs subtype/window fields when
        // bounds exist; applyTargetWindow covers the CGEvent fallback path.
        applyTargetWindow(windowID, to: event)
        ComputerUseSyntheticInputMarker.apply(to: event)
        event.postToPid(pid)
        // The reference async send waits 0.1s between the components of a
        // multi-event click. Keep a shorter gap for move, down and up so total
        // latency stays reasonable while the posts remain separated.
        Thread.sleep(forTimeInterval: type == .leftMouseDown || type == .rightMouseDown || type == .otherMouseDown ? 0.1 : 0.03)
    }

    /// Codex `SynthesizedEvent.mouseEvent(..., windowUsesFlippedCoordinates:)`.
    static func targetedWindowMouseEvent(
        type: CGEventType,
        point: CGPoint,
        button: CGMouseButton,
        clickState: Int,
        windowID: CGWindowID?,
        windowBounds: CGRect?,
        windowUsesFlippedCoordinates: Bool = true
    ) -> CGEvent? {
        guard
            let windowID,
            let windowBounds,
            let eventType = appKitMouseEventType(for: type)
        else {
            return nil
        }

        let local = windowLocalPoint(
            globalPoint: point,
            windowBounds: windowBounds,
            windowUsesFlippedCoordinates: windowUsesFlippedCoordinates
        )

        guard
            let event = NSEvent.mouseEvent(
                with: eventType,
                location: local,
                modifierFlags: [],
                timestamp: ProcessInfo.processInfo.systemUptime,
                windowNumber: Int(windowID),
                context: nil,
                eventNumber: mouseEventNumber(for: type),
                clickCount: clickState,
                pressure: mouseEventPressure(for: type)
            ),
            let cgEvent = event.cgEvent
        else {
            return nil
        }

        // Match the reference `SynthesizedEvent.mouseEvent` field packing: flags
        // cleared by the caller, then location, the button in field 3, subtype 3
        // in field 7, and the window id in fields 0x5b and 0x5c.
        cgEvent.location = point
        cgEvent.setIntegerValueField(
            .mouseEventButtonNumber,
            value: Int64(button.rawValue)
        )
        cgEvent.setIntegerValueField(.mouseEventSubtype, value: 3)
        cgEvent.setIntegerValueField(
            .mouseEventWindowUnderMousePointer,
            value: Int64(windowID)
        )
        cgEvent.setIntegerValueField(
            .mouseEventWindowUnderMousePointerThatCanHandleThisEvent,
            value: Int64(windowID)
        )
        // Official `mouseEvent` ends by stamping the *window-local*
        // point through a private WindowServer SPI:
        //
        //   local = CGPointApplyAffineTransform(getLocation(event),
        //                                       translate(-bounds.minX, -bounds.minY))
        //   if <flag> { local.y = height - local.y }
        //   WindowServerSPI.setWindowLocation(event, local)
        //
        // We used to skip this entirely and rely on `NSEvent(location:) → .cgEvent`
        // carrying `locationInWindow`, which it does not. Pass the same `local` the
        // NSEvent was built with so both agree — deriving it again from the binary's
        // flag polarity would risk disagreeing with our own NSEvent.
        //
        // Do **not** "fix" this to the top-left-origin form that scroll needs
        // (`windowServerLocalPoint`): measured, that breaks background clicks on
        // classic AppKit windows (both fixture click tests time out). Mouse events
        // carry an NSEvent-derived `locationInWindow` and the two must agree;
        // scroll events have no NSEvent behind them, which is why the conventions
        // differ.
        WindowServerEventSPI.setWindowLocation(cgEvent, location: local)
        return cgEvent
    }

    private static func appKitMouseEventType(
        for type: CGEventType
    ) -> NSEvent.EventType? {
        switch type {
        case .mouseMoved:
            return .mouseMoved
        case .leftMouseDown:
            return .leftMouseDown
        case .leftMouseUp:
            return .leftMouseUp
        case .leftMouseDragged:
            return .leftMouseDragged
        case .rightMouseDown:
            return .rightMouseDown
        case .rightMouseUp:
            return .rightMouseUp
        case .rightMouseDragged:
            return .rightMouseDragged
        case .otherMouseDown:
            return .otherMouseDown
        case .otherMouseUp:
            return .otherMouseUp
        case .otherMouseDragged:
            return .otherMouseDragged
        default:
            return nil
        }
    }

    private static func mouseEventNumber(for type: CGEventType) -> Int {
        switch type {
        case .leftMouseDown, .rightMouseDown, .otherMouseDown:
            return 1
        case .leftMouseUp, .rightMouseUp, .otherMouseUp:
            return 2
        default:
            return 0
        }
    }

    private static func mouseEventPressure(for type: CGEventType) -> Float {
        switch type {
        case .leftMouseDown, .rightMouseDown, .otherMouseDown,
             .leftMouseDragged, .rightMouseDragged, .otherMouseDragged:
            return 1
        default:
            return 0
        }
    }

    static func applyTargetWindow(_ windowID: CGWindowID?, to event: CGEvent) {
        guard let windowID else {
            return
        }

        event.setIntegerValueField(.mouseEventSubtype, value: 3)
        event.setIntegerValueField(
            .mouseEventWindowUnderMousePointer,
            value: Int64(windowID)
        )
        event.setIntegerValueField(
            .mouseEventWindowUnderMousePointerThatCanHandleThisEvent,
            value: Int64(windowID)
        )
    }

    private static func wheel1(direction: String, pages: Double) -> Int32 {
        switch direction {
        case "up":
            return scrollWheelDelta(for: pages)
        case "down":
            return -scrollWheelDelta(for: pages)
        default:
            return 0
        }
    }

    private static func wheel2(direction: String, pages: Double) -> Int32 {
        switch direction {
        case "left":
            return scrollWheelDelta(for: pages)
        case "right":
            return -scrollWheelDelta(for: pages)
        default:
            return 0
        }
    }

    private static func scrollWheelDelta(for pages: Double) -> Int32 {
        let rawValue = (12.0 * pages).rounded(.toNearestOrAwayFromZero)
        let clamped = min(Double(Int32.max), max(1, rawValue))
        return Int32(clamped)
    }
}
